# ee/pocketpaw_ee/cloud/models/social_idea.py — one Growth › Social short-form
# post idea (format, hook, on-screen text, script beats, caption, hashtags and
# the one-line "why"), scoped to a workspace and one social profile, with a
# new → approved / skipped review status, and, once scheduled, the date and
# the /calendar event that marks it. Ideas are generated by the social
# ideas agent and reviewed in Blitz. ``source`` says who asked: "manual" (a
# person) or "daily" (the morning drafting sweep, which also stamps
# ``suggested_at``, the time it suggests posting). Rows written before
# ``source`` existed have no key and read as "manual". ``post_ids`` are the
# Postiz post ids of every successful post made from the idea (now or
# scheduled); older rows read as empty. ``published_url`` / ``published_at`` /
# ``x_post_id`` record the live X post once the metrics sweep finds it in
# Postiz; empty until then (and on older rows). ``pillar`` / ``hook_type`` are
# short free-text tags (at most 40 characters) the review averages over;
# ``experiment_id`` names the experiment whose arm this daily draft was written
# for. All three read as "" on older rows.
#
# Only ``ee.cloud.growth.social.service`` may import this doc class
# (import-linter "Growth" contract).

from __future__ import annotations

from datetime import datetime

from beanie import Indexed
from pydantic import Field

from pocketpaw_ee.cloud.models.base import TimestampedDocument


class SocialIdea(TimestampedDocument):
    """One generated post idea in a workspace."""

    workspace: Indexed(str)  # type: ignore[valid-type]
    profile: str = ""
    format: str
    hook: str
    on_screen_text: str = ""
    caption: str = ""
    why: str = ""
    script: list[str] = Field(default_factory=list)
    hashtags: list[str] = Field(default_factory=list)
    platform: str = ""
    subreddit: str = ""
    status: str = "new"
    scheduled_at: datetime | None = None
    calendar_event_id: str = ""
    poster_svg: str = ""
    reel_html: str = ""
    media_choice: str = ""
    source: str = "manual"
    suggested_at: datetime | None = None
    post_ids: list[str] = Field(default_factory=list)
    published_url: str = ""
    published_at: datetime | None = None
    x_post_id: str = ""
    pillar: str = ""
    hook_type: str = ""
    experiment_id: str = ""

    class Settings:
        name = "growth_social_ideas"
        indexes = [
            [("workspace", 1), ("profile", 1), ("status", 1), ("createdAt", -1)],
            [("workspace", 1), ("profile", 1), ("createdAt", -1)],
        ]
